	// (POST /auth/refresh)
	RefreshSession(c *gin.Context)
	// Register Create an account
	// (POST /auth/register)
	Register(c *gin.Context)
	// VerifyEmail Confirm an email address
	// (POST /auth/verify)
	VerifyEmail(c *gin.Context)
	// GetHealth Service and database health
	// (GET /healthz)
	GetHealth(c *gin.Context)
